ollowing_url":"https://api.github.com/users/BaoTo12/following{/other_user}","gists_url":"https://api.github.com/users/BaoTo12/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/BaoTo12","id":117547743,"login":"BaoTo12","node_id":"U_kgDOBwGi3w","organizations_url":"https://api.github.com/users/BaoTo12/orgs","received_events_url":"https://api.github.com/users/BaoTo12/received_events","repos_url":"https://api.github.com/users/BaoTo12/repos","site_admin":false,"starred_url":"https://api.github.com/users/BaoTo12/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/BaoTo12/subscriptions","type":"User","url":"https://api.github.com/users/BaoTo12","user_view_type":"public"},"comments_url":"https://api.github.com/repos/BaoTo12/go-ecommerce-v2/commits/d0863478ecd85fd13fd9681ccf86aebe923d7f02/comments","commit":{"author":{"date":"2025-12-04T06:31:32Z","email":"baotochi87@gmail.com","name":"ChiBao"},"comment_count":0,"committer":{"date":"2025-12-04T06:31:32Z","email":"baotochi87@gmail.com","name":"ChiBao"},"message":"fix: Created proto stubs and fixed compilation errors\n\n- Fixed pkg/logger io.Writer type mismatch\n- Fixed PaymentGateway type/interface conflict\n- Created proto stub .pb.go files for all 18 services\n- Simplified Product domain model to match API\n- Used context.Context in all proto stubs","tree":{"sha":"ec37a26e5380a2c8dc6cd762fdbe1483ea49e926","url":"https://api.github.com/repos/BaoTo12/go-ecommerce-v2/git/trees/ec37a26e5380a2c8dc6cd762fdbe1483ea49e926"},"url":"https://api.github.com/repos/BaoTo12/go-ecommerce-v2/git/commits/d0863478ecd85fd13fd9681ccf86aebe923d7f02","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/117547743?v=4","events_url":"https://api.github.com/users/BaoTo12/events{/privacy}","followers_url":"https://api.github.com/users/BaoTo12/followers","following_url":"https://api.github.com/use